/**
 * Core navigation graph type definitions for CampusNav.
 *
 * Two categories of types:
 *
 * 1. **ngraph.graph data types** — `NavNodeData` and `NavEdgeData` are the `.data`
 *    fields stored on ngraph.graph's Node and Link objects via
 *    `graph.addNode(id, data)` and `graph.addLink(from, to, data)`.
 *
 * 2. **Serialization types** — `NavNode`, `NavEdge`, `NavFloor`, `NavBuilding`,
 *    and `NavGraph` are the JSON shapes used for API transport (GET /api/map) and
 *    file storage. The client loads a `NavGraph`, iterates `buildings[].floors[]`,
 *    destructures each node/edge into `(id, data)`, and feeds them into ngraph.graph.
 *    `NavNode` objects live inside `NavFloor.nodes[]`.
 *
 * All coordinates are **NORMALIZED** (0.0–1.0), representing percentages of the
 * floor plan image dimensions. Convert to pixels only at render time:
 * `pixelX = node.x * canvasWidth`.
 */

// ============================================================
// Node Types
// ============================================================

/**
 * Classification of navigation nodes on a floor plan.
 *
 * **Visible to students** (searchable destinations):
 * - `room` — Classroom, office, lab
 * - `entrance` — Building entrance/exit
 * - `elevator` — Elevator (also an accessibility waypoint)
 * - `restroom` — Restroom
 * - `landmark` — Named point of interest (cafeteria, library)
 *
 * **Invisible to students** (routing infrastructure only):
 * - `stairs` — Stairwell navigation waypoint, HIDDEN from student map (routing infrastructure only)
 * - `ramp` — Ramp navigation waypoint, HIDDEN from student map (routing infrastructure only)
 * - `junction` — Hallway intersection
 * - `hallway` — Mid-hallway point
 */
export type NavNodeType =
  | 'room'
  | 'entrance'
  | 'elevator'
  | 'stairs'
  | 'ramp'
  | 'restroom'
  | 'junction'
  | 'hallway'
  | 'landmark'

/**
 * Data stored on each graph node (the `.data` field of an ngraph.graph Node).
 *
 * Coordinates are normalized 0.0–1.0: percentage of floor plan width/height.
 */
export interface NavNodeData {
  /** Normalized x position (0.0 = left edge, 1.0 = right edge of floor plan) */
  x: number
  /** Normalized y position (0.0 = top edge, 1.0 = bottom edge of floor plan) */
  y: number
  /** Display label for search results and turn-by-turn directions */
  label: string
  /** Node classification — determines visibility and search behavior */
  type: NavNodeType
  /** Whether this node appears in student search results */
  searchable: boolean
  /** ID of the floors record this node belongs to (FK → floors.id) */
  floorId: number
  // buildingName REMOVED — derived transitively via floor → building
  /** Room/office number identifier (e.g. "204", "A-102") */
  roomNumber?: string
  /** Human-readable description shown in location detail sheet */
  description?: string
  /** Accessibility information shown in detail sheet */
  accessibilityNotes?: string
  // Floor connector linkage — only set on stairs, elevator, ramp nodes
  /** ID of the floor above that this connector node links to */
  connectsToFloorAboveId?: number
  /** ID of the floor below that this connector node links to */
  connectsToFloorBelowId?: number
  /** ID of the corresponding node on the floor above */
  connectsToNodeAboveId?: string
  /** ID of the corresponding node on the floor below */
  connectsToNodeBelowId?: string
  /** ID of the building this campus entrance marker bridges to (campus map only, entrance nodes) */
  connectsToBuildingId?: number
}

// ============================================================
// Edge Types
// ============================================================

/**
 * Data stored on each graph edge (the `.data` field of an ngraph.graph Link).
 *
 * Every edge carries **dual weights** to enable accessibility routing:
 * - `standardWeight`: cost for the standard walking route
 * - `accessibleWeight`: cost for the wheelchair-accessible route
 *   (same as standard for flat paths; higher for detours like ramps;
 *   `Infinity` for non-accessible edges like stairs)
 */
export interface NavEdgeData {
  /**
   * Walking cost for the standard route.
   * Typically the Euclidean distance between connected nodes in normalized
   * coordinates. Can be overridden by an admin for non-straight paths.
   */
  standardWeight: number
  /**
   * Walking cost for the wheelchair-accessible route.
   * - Same as `standardWeight` for accessible paths.
   * - Higher than `standardWeight` if the accessible path is longer (e.g. ramp).
   * - `Infinity` for non-accessible edges (e.g. stairs without elevator).
   */
  accessibleWeight: number
  /** Whether this edge is traversable by wheelchair */
  accessible: boolean
  /** Whether this edge can be traversed in both directions */
  bidirectional: boolean
  /** Optional admin notes ("3 steps", "narrow doorway", "automatic door") */
  accessibilityNotes?: string
}

// ============================================================
// Serialization Types (API / JSON transport)
// ============================================================

/**
 * A serialized node for JSON transport (API responses, file storage).
 * Combines the node's unique ID with its data fields.
 * NavNode inherits `floorId` from NavNodeData — no direct change needed.
 */
export interface NavNode extends NavNodeData {
  /** Unique identifier for this node (e.g. "room-204", "entrance-main") */
  id: string
}

/**
 * A serialized edge for JSON transport (API responses, file storage).
 * Combines the edge's ID, endpoint references, and data fields.
 */
export interface NavEdge extends NavEdgeData {
  /** Unique identifier for this edge */
  id: string
  /** Source node ID */
  sourceId: string
  /** Target node ID */
  targetId: string
}

/**
 * Optional real-world GPS bounds used to project normalized floor coordinates
 * onto latitude/longitude space.
 */
export interface NavFloorGpsBounds {
  /** Minimum latitude represented by this floor map */
  minLat: number
  /** Maximum latitude represented by this floor map */
  maxLat: number
  /** Minimum longitude represented by this floor map */
  minLng: number
  /** Maximum longitude represented by this floor map */
  maxLng: number
}

/**
 * A single floor within a building, containing all nodes and edges on that floor.
 */
export interface NavFloor {
  /** Database ID of this floor record (floors.id) */
  id: number
  /** Floor number (1-based) */
  floorNumber: number
  /** Path to the floor plan image asset */
  imagePath: string
  /** ISO 8601 timestamp of last graph modification */
  updatedAt: string
  /** Optional GPS calibration bounds for this floor */
  gpsBounds?: NavFloorGpsBounds
  /** All navigation nodes on this floor */
  nodes: NavNode[]
  /** All navigation edges on this floor */
  edges: NavEdge[]
}

/**
 * A building containing one or more floors.
 */
export interface NavBuilding {
  /** Database ID of this building record (buildings.id) */
  id: number
  /** Display name of the building */
  name: string
  /** All floors within this building */
  floors: NavFloor[]
}

/**
 * Complete navigation graph as JSON — returned by `GET /api/map`.
 *
 * The client loads this on page init and builds an ngraph.graph instance
 * by iterating the nested buildings → floors → nodes/edges structure:
 * ```ts
 * const graph = createGraph<NavNodeData, NavEdgeData>()
 * for (const building of navGraph.buildings) {
 *   for (const floor of building.floors) {
 *     for (const { id, ...data } of floor.nodes) graph.addNode(id, data)
 *     for (const { id, sourceId, targetId, ...data } of floor.edges)
 *       graph.addLink(sourceId, targetId, data)
 *   }
 * }
 * ```
 */
export interface NavGraph {
  /** All buildings in the campus, each containing floors with nodes and edges */
  buildings: NavBuilding[]
  // nodes and edges now live under buildings[].floors[].nodes/edges
  // metadata replaced by floors[].updatedAt
}

/**
 * Graph construction from NavGraph JSON.
 *
 * Builds a typed ngraph.graph instance from a serialized NavGraph object,
 * handling bidirectional edge expansion and cross-floor edge synthesis.
 * Also exports a Euclidean distance utility used for edge weight calculation
 * and A* heuristic.
 */

import type { NavEdge, NavEdgeData, NavGraph, NavNode, NavNodeData } from '@shared/types'
import type { Graph } from 'ngraph.graph'
import createGraph from 'ngraph.graph'

/**
 * Flattens a multi-floor NavGraph into a single list of nodes and edges.
 *
 * Retained for the admin map editor (MapEditorCanvas.tsx) which depends on
 * this function to flatten the NavGraph before editing and re-wrap it on save.
 * This function is NOT called inside buildGraph as of Phase 17.
 */
export function flattenNavGraph(navGraph: NavGraph): { nodes: NavNode[]; edges: NavEdge[] } {
  const nodes: NavNode[] = []
  const edges: NavEdge[] = []
  for (const building of navGraph.buildings) {
    for (const floor of building.floors) {
      nodes.push(...floor.nodes)
      edges.push(...floor.edges)
    }
  }
  return { nodes, edges }
}

/**
 * Constructs a live ngraph.graph from a serialized NavGraph JSON object.
 *
 * Phase 17 implementation: iterates buildings → floors directly (no longer
 * calls flattenNavGraph internally). After all nodes and intra-floor edges
 * are added, performs a second pass to synthesize bidirectional inter-floor
 * edges from connectsToNodeAboveId on stairs, elevator, and ramp nodes.
 *
 * Inter-floor edge weights:
 * - stairs: standardWeight=0.3, accessibleWeight=Infinity, accessible=false
 * - elevator/ramp: standardWeight=0.3, accessibleWeight=0.45, accessible=true
 *
 * For each node: destructures `{ id, ...data }` and adds to graph.
 * For each intra-floor edge: adds a directed link. If `bidirectional` is true,
 * also adds the reverse directed link so both `graph.getLink(a, b)`
 * and `graph.getLink(b, a)` return a link.
 *
 * The pathfinding engine uses x, y, and weight fields for routing; extra
 * fields (floorId, connector IDs) are stored as node data and passed through.
 */
export function buildGraph(navGraph: NavGraph): Graph<NavNodeData, NavEdgeData> {
  const graph = createGraph<NavNodeData, NavEdgeData>()

  // Pass 1: add all nodes and intra-floor edges from all buildings and floors.
  for (const building of navGraph.buildings) {
    for (const floor of building.floors) {
      for (const { id, ...data } of floor.nodes) {
        graph.addNode(id, data)
      }

      for (const { id: _id, sourceId, targetId, ...data } of floor.edges) {
        // Normalize accessibleWeight to Infinity for non-accessible edges.
        // JSON cannot represent Infinity, so the serialized form uses a large
        // finite number. The graph should carry the true semantic value.
        const edgeData: NavEdgeData = data.accessible
          ? data
          : { ...data, accessibleWeight: Number.POSITIVE_INFINITY }
        graph.addLink(sourceId, targetId, edgeData)
        if (edgeData.bidirectional) {
          graph.addLink(targetId, sourceId, edgeData)
        }
      }
    }
  }

  // Pass 2: synthesize bidirectional inter-floor edges from connector nodes.
  // Only process connectsToNodeAboveId to avoid adding each pair twice
  // (the counterpart node on the floor above has connectsToNodeBelowId pointing
  // back, which would duplicate the edge if we processed both directions here).
  const processedPairs = new Set<string>()

  graph.forEachNode((node) => {
    const data = node.data
    const nodeType = data.type

    if (
      (nodeType === 'stairs' || nodeType === 'elevator' || nodeType === 'ramp') &&
      data.connectsToNodeAboveId != null
    ) {
      const targetId = data.connectsToNodeAboveId
      if (!graph.hasNode(targetId)) return

      // Build a canonical pair key (sorted) to skip duplicates.
      const pairKey = [node.id, targetId].sort().join('|')
      if (processedPairs.has(pairKey)) return
      processedPairs.add(pairKey)

      // Skip if links already exist (e.g. JSON stored inter-floor edges).
      if (graph.hasLink(node.id, targetId) || graph.hasLink(targetId, node.id)) return

      const isAccessible = nodeType === 'elevator' || nodeType === 'ramp'
      const interFloorEdge: NavEdgeData = {
        standardWeight: 0.3,
        accessibleWeight: isAccessible ? 0.45 : Number.POSITIVE_INFINITY,
        accessible: isAccessible,
        bidirectional: true,
      }

      graph.addLink(node.id, targetId, interFloorEdge)
      graph.addLink(targetId, node.id, interFloorEdge)
    }
  })

  return graph
}

/**
 * Computes Euclidean distance between two points.
 *
 * Used by:
 * - Admin editor (Phase 9) to auto-compute edge weights from node coordinates
 * - Pathfinding engine (Plan 02) as the A* heuristic function
 *
 * @param ax - X coordinate of point A
 * @param ay - Y coordinate of point A
 * @param bx - X coordinate of point B
 * @param by - Y coordinate of point B
 * @returns Euclidean distance between the two points
 */
export function calculateWeight(ax: number, ay: number, bx: number, by: number): number {
  return Math.sqrt((ax - bx) ** 2 + (ay - by) ** 2)
}

export const STARTUP_TIMEOUT_MS = 3_000;

export type BootstrapPhase = 'idle' | 'loading' | 'ready' | 'error';

export type BootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | 'startup-timeout'
  | 'startup-tooling-error'
  | 'invalid-startup-config';

export type BootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: BootstrapErrorReason;
      message: string;
      failedPhase: 'loading';
      recoverable: boolean;
    };

export interface BootstrapResult {
  state: BootstrapState;
  transitions: BootstrapState[];
}

export interface BootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  timeoutMs?: number;
  now?: () => number;
  toolingCheck?: () => Promise<unknown>;
}

interface ValidUrlResult {
  ok: true;
  normalizedUrl: string;
}

interface InvalidUrlResult {
  ok: false;
  reason: Extract<BootstrapErrorReason, 'missing-api-base-url' | 'invalid-api-base-url'>;
  message: string;
}

const DEFAULT_IDLE_STATE: BootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_BOOTSTRAP_STATE = DEFAULT_IDLE_STATE;

export function createLoadingState(attempt: number, now: () => number): BootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
  };
}

export function validateApiBaseUrl(rawValue: string | undefined): ValidUrlResult | InvalidUrlResult {
  const value = rawValue?.trim();

  if (!value) {
    return {
      ok: false,
      reason: 'missing-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL is missing.',
    };
  }

  try {
    const parsed = new URL(value);

    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return {
        ok: false,
        reason: 'invalid-api-base-url',
        message: 'EXPO_PUBLIC_API_BASE_URL must use http or https.',
      };
    }

    parsed.hash = '';

    return {
      ok: true,
      normalizedUrl: parsed.toString().replace(/\/$/, ''),
    };
  } catch {
    return {
      ok: false,
      reason: 'invalid-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL must be a valid absolute URL.',
    };
  }
}

function toBootstrapError(
  reason: BootstrapErrorReason,
  message: string,
  attempt: number,
  recoverable = true,
): BootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'loading',
    recoverable,
  };
}

function isValidStartupToolingResult(result: unknown): result is { status: 'ok' } {
  return !!result && typeof result === 'object' && (result as { status?: string }).status === 'ok';
}

async function defaultToolingCheck(): Promise<{ status: 'ok' }> {
  return { status: 'ok' };
}

async function runWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timeoutHandle = setTimeout(() => {
      reject(new Error(message));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timeoutHandle) {
      clearTimeout(timeoutHandle);
    }
  }
}

export async function runAppBootstrap(options: BootstrapOptions = {}): Promise<BootstrapResult> {
  const now = options.now ?? Date.now;
  const attempt = Math.max(1, options.attempt ?? 1);
  const timeoutMs = options.timeoutMs ?? STARTUP_TIMEOUT_MS;
  const toolingCheck = options.toolingCheck ?? defaultToolingCheck;
  const env = options.env ?? process.env;

  const loadingState = createLoadingState(attempt, now);
  const transitions: BootstrapState[] = [loadingState];

  try {
    const toolingResult = await runWithTimeout(
      toolingCheck(),
      timeoutMs,
      'Startup tooling check timed out.',
    );

    if (!isValidStartupToolingResult(toolingResult)) {
      const malformedConfigState = toBootstrapError(
        'invalid-startup-config',
        'Startup tooling returned an invalid configuration shape.',
        attempt,
        false,
      );
      transitions.push(malformedConfigState);
      return {
        state: malformedConfigState,
        transitions,
      };
    }
  } catch (error) {
    const reason: BootstrapErrorReason =
      error instanceof Error && error.message === 'Startup tooling check timed out.'
        ? 'startup-timeout'
        : 'startup-tooling-error';

    const toolingErrorState = toBootstrapError(
      reason,
      error instanceof Error ? error.message : 'Startup tooling check failed.',
      attempt,
      true,
    );
    transitions.push(toolingErrorState);

    return {
      state: toolingErrorState,
      transitions,
    };
  }

  const apiValidation = validateApiBaseUrl(env.EXPO_PUBLIC_API_BASE_URL);

  if (!apiValidation.ok) {
    const configErrorState = toBootstrapError(
      apiValidation.reason,
      apiValidation.message,
      attempt,
      false,
    );
    transitions.push(configErrorState);

    return {
      state: configErrorState,
      transitions,
    };
  }

  const readyState: BootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiValidation.normalizedUrl,
  };
  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';

import {
  IDLE_BOOTSTRAP_STATE,
  type BootstrapState,
  runAppBootstrap,
} from './bootstrap/appBootstrap';

function nextAttemptFromState(state: BootstrapState): number {
  if (state.phase === 'idle') {
    return 1;
  }

  return state.attempt + 1;
}

function phaseMessage(state: BootstrapState): string {
  switch (state.phase) {
    case 'idle':
      return 'Preparing startup checks.';
    case 'loading':
      return 'Starting CampusNav runtime.';
    case 'ready':
      return 'CampusNav is ready. No sign-in required.';
    case 'error':
      return state.message;
  }
}

export default function App() {
  const [bootstrapState, setBootstrapState] = useState<BootstrapState>(IDLE_BOOTSTRAP_STATE);

  const executeBootstrap = useCallback(async (attempt: number) => {
    const result = await runAppBootstrap({ attempt });

    for (const transition of result.transitions) {
      if (transition.phase === 'ready') {
        console.info('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
          endpoint: transition.apiBaseUrl,
        });
        continue;
      }

      if (transition.phase === 'error') {
        console.warn('[mobile-bootstrap]', {
          phase: transition.phase,
          reason: transition.reason,
          attempt: transition.attempt,
          failedPhase: transition.failedPhase,
        });
        continue;
      }

      if (transition.phase === 'loading') {
        console.info('[mobile-bootstrap]', {
          phase: transition.phase,
          attempt: transition.attempt,
        });
      }
    }

    setBootstrapState(result.state);
  }, []);

  useEffect(() => {
    void executeBootstrap(1);
  }, [executeBootstrap]);

  const onRetryPress = () => {
    void executeBootstrap(nextAttemptFromState(bootstrapState));
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>CampusNav</Text>
      <Text style={styles.subtitle}>Visitor bootstrap shell</Text>

      <Text style={styles.statusLabel}>Bootstrap phase: {bootstrapState.phase}</Text>
      <Text style={styles.statusMessage}>{phaseMessage(bootstrapState)}</Text>

      {bootstrapState.phase === 'loading' ? <ActivityIndicator size="small" color="#38bdf8" /> : null}

      {bootstrapState.phase === 'ready' ? (
        <Text style={styles.readyText}>API endpoint: {bootstrapState.apiBaseUrl}</Text>
      ) : null}

      {bootstrapState.phase === 'error' ? (
        <View style={styles.errorContainer}>
          <Text style={styles.errorReason}>Reason: {bootstrapState.reason}</Text>
          <Pressable onPress={onRetryPress} style={styles.retryButton}>
            <Text style={styles.retryButtonText}>Retry startup</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

