import type { NavGraph, NavNode, NavNodeType } from '@shared/types'

export type ConnectorDirection = 'above' | 'below'
export type ConnectorNodeType = Extract<NavNodeType, 'stairs' | 'elevator' | 'ramp'>

const CONNECTOR_NODE_TYPES = new Set<ConnectorNodeType>(['stairs', 'elevator', 'ramp'])

export interface ConnectorCandidate {
  nodeId: string
  floorId: number
  floorNumber: number
  buildingId: number
  buildingName: string
  label: string
  nodeType: ConnectorNodeType
}

export interface ConnectorCandidateLists {
  above: ConnectorCandidate[]
  below: ConnectorCandidate[]
}

export interface ConnectorUpdatedNode {
  id: string
  floorId: number
  connectsToFloorAboveId: number | null
  connectsToFloorBelowId: number | null
  connectsToNodeAboveId: string | null
  connectsToNodeBelowId: string | null
}

interface FloorLookup {
  floorId: number
  floorNumber: number
  buildingId: number
  buildingName: string
  nodes: NavNode[]
}

interface ConnectorLookups {
  floorById: Map<number, FloorLookup>
  floorByBuildingAndNumber: Map<string, FloorLookup>
  connectorNodesByFloorId: Map<number, Array<NavNode & { type: ConnectorNodeType }>>
}

function floorKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`
}

export function isConnectorNodeType(type: NavNodeType): type is ConnectorNodeType {
  return CONNECTOR_NODE_TYPES.has(type as ConnectorNodeType)
}

function buildLookups(navGraph: NavGraph): ConnectorLookups {
  const floorById = new Map<number, FloorLookup>()
  const floorByBuildingAndNumber = new Map<string, FloorLookup>()
  const connectorNodesByFloorId = new Map<number, Array<NavNode & { type: ConnectorNodeType }>>()

  for (const building of navGraph.buildings) {
    for (const floor of building.floors) {
      const floorLookup: FloorLookup = {
        floorId: floor.id,
        floorNumber: floor.floorNumber,
        buildingId: building.id,
        buildingName: building.name,
        nodes: floor.nodes,
      }

      floorById.set(floor.id, floorLookup)
      floorByBuildingAndNumber.set(floorKey(building.id, floor.floorNumber), floorLookup)

      connectorNodesByFloorId.set(
        floor.id,
        floor.nodes.filter(
          (node): node is NavNode & { type: ConnectorNodeType } => isConnectorNodeType(node.type),
        ),
      )
    }
  }

  return {
    floorById,
    floorByBuildingAndNumber,
    connectorNodesByFloorId,
  }
}

function toCandidates(
  floor: FloorLookup | undefined,
  sourceNodeId: string,
  connectorNodesByFloorId: Map<number, Array<NavNode & { type: ConnectorNodeType }>>,
): ConnectorCandidate[] {
  if (!floor) return []

  const nodes = connectorNodesByFloorId.get(floor.floorId) ?? []

  return nodes
    .filter((node) => node.id !== sourceNodeId)
    .map((node) => ({
      nodeId: node.id,
      floorId: floor.floorId,
      floorNumber: floor.floorNumber,
      buildingId: floor.buildingId,
      buildingName: floor.buildingName,
      label: node.label,
      nodeType: node.type,
    }))
    .sort((left, right) => {
      if (left.floorNumber !== right.floorNumber) {
        return left.floorNumber - right.floorNumber
      }

      const labelCmp = left.label.localeCompare(right.label)
      if (labelCmp !== 0) return labelCmp

      return left.nodeId.localeCompare(right.nodeId)
    })
}

export function deriveConnectorCandidates(
  navGraph: NavGraph | null,
  sourceNode: NavNode | null,
): ConnectorCandidateLists {
  if (!navGraph || !sourceNode || !isConnectorNodeType(sourceNode.type)) {
    return { above: [], below: [] }
  }

  const lookups = buildLookups(navGraph)
  const sourceFloor = lookups.floorById.get(sourceNode.floorId)
  if (!sourceFloor) {
    return { above: [], below: [] }
  }

  const aboveFloor = lookups.floorByBuildingAndNumber.get(
    floorKey(sourceFloor.buildingId, sourceFloor.floorNumber + 1),
  )
  const belowFloor = lookups.floorByBuildingAndNumber.get(
    floorKey(sourceFloor.buildingId, sourceFloor.floorNumber - 1),
  )

  return {
    above: toCandidates(aboveFloor, sourceNode.id, lookups.connectorNodesByFloorId),
    below: toCandidates(belowFloor, sourceNode.id, lookups.connectorNodesByFloorId),
  }
}

function applyConnectorPatch(node: NavNode, update: ConnectorUpdatedNode): NavNode {
  const {
    connectsToFloorAboveId: _oldAboveFloorId,
    connectsToFloorBelowId: _oldBelowFloorId,
    connectsToNodeAboveId: _oldAboveNodeId,
    connectsToNodeBelowId: _oldBelowNodeId,
    ...baseNode
  } = node

  return {
    ...baseNode,
    ...(update.connectsToFloorAboveId !== null
      ? { connectsToFloorAboveId: update.connectsToFloorAboveId }
      : {}),
    ...(update.connectsToFloorBelowId !== null
      ? { connectsToFloorBelowId: update.connectsToFloorBelowId }
      : {}),
    ...(update.connectsToNodeAboveId !== null
      ? { connectsToNodeAboveId: update.connectsToNodeAboveId }
      : {}),
    ...(update.connectsToNodeBelowId !== null
      ? { connectsToNodeBelowId: update.connectsToNodeBelowId }
      : {}),
  }
}

export function applyConnectorUpdatesToFloorNodes(
  nodes: NavNode[],
  updatedNodes: ConnectorUpdatedNode[],
): NavNode[] {
  if (updatedNodes.length === 0) return nodes

  const updatesByNodeId = new Map(updatedNodes.map((node) => [node.id, node]))
  let hasChanges = false

  const nextNodes = nodes.map((node) => {
    const update = updatesByNodeId.get(node.id)
    if (!update) return node

    hasChanges = true
    return applyConnectorPatch(node, update)
  })

  return hasChanges ? nextNodes : nodes
}

export function applyConnectorUpdatesToNavGraph(
  navGraph: NavGraph | null,
  updatedNodes: ConnectorUpdatedNode[],
): NavGraph | null {
  if (!navGraph || updatedNodes.length === 0) return navGraph

  const updatesByNodeId = new Map(updatedNodes.map((node) => [node.id, node]))
  const affectedFloorIds = new Set(updatedNodes.map((node) => node.floorId))
  let graphChanged = false

  const nextBuildings = navGraph.buildings.map((building) => {
    let buildingChanged = false

    const nextFloors = building.floors.map((floor) => {
      if (!affectedFloorIds.has(floor.id)) {
        return floor
      }

      const nextNodes = floor.nodes.map((node) => {
        const update = updatesByNodeId.get(node.id)
        if (!update) return node

        buildingChanged = true
        return applyConnectorPatch(node, update)
      })

      if (!buildingChanged) {
        return floor
      }

      return {
        ...floor,
        nodes: nextNodes,
      }
    })

    if (!buildingChanged) {
      return building
    }

    graphChanged = true

    return {
      ...building,
      floors: nextFloors,
    }
  })

  if (!graphChanged) {
    return navGraph
  }

  return {
    buildings: nextBuildings,
  }
}

export function formatConnectorCandidateLabel(candidate: ConnectorCandidate): string {
  const displayLabel = candidate.label.trim().length > 0 ? candidate.label : candidate.nodeId
  const nodeTypeLabel = candidate.nodeType.charAt(0).toUpperCase() + candidate.nodeType.slice(1)
  return `Floor ${candidate.floorNumber} · ${displayLabel} (${nodeTypeLabel})`
}

import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { eq } from 'drizzle-orm'
import { db } from './client'
import { buildings, edges, floors, nodes } from './schema'

const __dirname = dirname(fileURLToPath(import.meta.url))

// Local types matching the nested JSON seed format.
// NavGraph is the API type (with floorId on nodes); SeedGraph is the simpler seed-file type.
type SeedNode = {
  id: string
  x: number
  y: number
  label: string
  type: string
  searchable: boolean
  roomNumber?: string
  description?: string
  accessibilityNotes?: string
}
type SeedEdge = {
  id: string
  sourceId: string
  targetId: string
  standardWeight: number
  accessibleWeight: number
  accessible: boolean
  bidirectional: boolean
  accessibilityNotes?: string
}
type SeedFloor = { floorNumber: number; imagePath: string; nodes: SeedNode[]; edges: SeedEdge[] }
type SeedBuilding = { id: number; name: string; floors: SeedFloor[] }
type SeedGraph = { buildings: SeedBuilding[] }

export async function seedIfEmpty(): Promise<void> {
  // Cheap count check — no-op if already seeded
  const existing = await db.select().from(nodes)
  if (existing.length > 0) {
    console.log(`[seed] Already seeded (${existing.length} nodes) — skipping`)
    return
  }

  const filePath = resolve(__dirname, '../assets/campus-graph.json')
  const graph: SeedGraph = JSON.parse(readFileSync(filePath, 'utf-8'))

  let totalNodes = 0
  let totalEdges = 0

  for (const b of graph.buildings) {
    // Reuse existing building if the migration already created one with the same name
    const existingBuilding = await db.select({ id: buildings.id }).from(buildings).where(eq(buildings.name, b.name))
    let buildingId: number
    if (existingBuilding.length > 0 && existingBuilding[0]) {
      buildingId = existingBuilding[0].id
    } else {
      const inserted = await db.insert(buildings).values({ name: b.name }).returning({ id: buildings.id })
      if (!inserted[0]) throw new Error(`[seed] Failed to insert building: ${b.name}`)
      buildingId = inserted[0].id
    }

    for (const f of b.floors) {
      const floorRows = await db.insert(floors).values({
        buildingId: buildingId,
        floorNumber: f.floorNumber,
        imagePath: f.imagePath,
        updatedAt: new Date().toISOString(),
      }).returning({ id: floors.id })
      const floor = floorRows[0]
      if (!floor) throw new Error(`[seed] Failed to insert floor: ${f.floorNumber} for building ${b.name}`)

      await db.insert(nodes).values(
        f.nodes.map((n) => ({
          id: n.id,
          x: n.x,
          y: n.y,
          label: n.label,
          type: n.type,
          searchable: n.searchable,
          floorId: floor.id, // assigned from RETURNING — not in JSON
          roomNumber: n.roomNumber ?? null,
          description: n.description ?? null,
          accessibilityNotes: n.accessibilityNotes ?? null,
          // connector linkage defaults to null for all seed nodes (none are cross-floor yet)
          connectsToFloorAboveId: null,
          connectsToFloorBelowId: null,
          connectsToNodeAboveId: null,
          connectsToNodeBelowId: null,
        }))
      ).onConflictDoNothing()

      await db.insert(edges).values(
        f.edges.map((e) => ({
          id: e.id,
          sourceId: e.sourceId,
          targetId: e.targetId,
          standardWeight: e.standardWeight,
          accessibleWeight: e.accessibleWeight, // Keep 1e10 as-is — DO NOT convert to Infinity (JSON cannot serialize Infinity)
          accessible: e.accessible,
          bidirectional: e.bidirectional,
          accessibilityNotes: e.accessibilityNotes ?? null,
        }))
      ).onConflictDoNothing()

      totalNodes += f.nodes.length
      totalEdges += f.edges.length
    }
  }

  console.log(`[seed] Inserted ${totalNodes} nodes, ${totalEdges} edges`)
}

import type { NavFloorGpsBounds } from '@shared/types'
import { eq } from 'drizzle-orm'
import { db } from './db/client'
import { floors } from './db/schema'

export interface FloorGpsBoundsColumns {
  gpsMinLat: number | null
  gpsMaxLat: number | null
  gpsMinLng: number | null
  gpsMaxLng: number | null
}

export type FloorGpsBoundsErrorCode =
  | 'INVALID_REQUEST'
  | 'GPS_BOUNDS_INCOMPLETE'
  | 'BOUNDS_RANGE_INVALID'
  | 'FLOOR_NOT_FOUND'

type FloorGpsBoundsErrorStatus = 400 | 404

const FLOOR_GPS_BOUNDS_ERROR_STATUS = {
  INVALID_REQUEST: 400,
  GPS_BOUNDS_INCOMPLETE: 400,
  BOUNDS_RANGE_INVALID: 400,
  FLOOR_NOT_FOUND: 404,
} as const satisfies Record<FloorGpsBoundsErrorCode, FloorGpsBoundsErrorStatus>

export class FloorGpsBoundsError extends Error {
  readonly code: FloorGpsBoundsErrorCode
  readonly status: FloorGpsBoundsErrorStatus

  constructor(code: FloorGpsBoundsErrorCode, message: string) {
    super(message)
    this.name = 'FloorGpsBoundsError'
    this.code = code
    this.status = FLOOR_GPS_BOUNDS_ERROR_STATUS[code]
  }
}

export interface FloorGpsBoundsUpdateResult {
  ok: true
  floorId: number
  gpsBounds: NavFloorGpsBounds | null
}

interface FloorGpsBoundsRow extends FloorGpsBoundsColumns {
  id: number
}

export interface FloorGpsBoundsStoreTx {
  getFloorById(floorId: number): Promise<FloorGpsBoundsRow | null>
  updateFloorGpsBounds(floorId: number, bounds: FloorGpsBoundsColumns): Promise<FloorGpsBoundsRow | null>
}

export interface FloorGpsBoundsStore {
  transaction<T>(callback: (tx: FloorGpsBoundsStoreTx) => Promise<T>): Promise<T>
}

type DrizzleFloorGpsBoundsTx = Pick<typeof db, 'select' | 'update'>

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

function parseFloorGpsBoundsTuple(values: {
  minLat: unknown
  maxLat: unknown
  minLng: unknown
  maxLng: unknown
}): FloorGpsBoundsColumns {
  const { minLat, maxLat, minLng, maxLng } = values
  const tupleValues = [minLat, maxLat, minLng, maxLng] as const

  if (tupleValues.some(value => value === undefined)) {
    throw new FloorGpsBoundsError(
      'GPS_BOUNDS_INCOMPLETE',
      'minLat, maxLat, minLng, and maxLng must all be provided',
    )
  }

  if (tupleValues.every(value => value === null)) {
    return {
      gpsMinLat: null,
      gpsMaxLat: null,
      gpsMinLng: null,
      gpsMaxLng: null,
    }
  }

  if (tupleValues.some(value => value === null)) {
    throw new FloorGpsBoundsError(
      'GPS_BOUNDS_INCOMPLETE',
      'GPS bounds must be a complete numeric tuple or a full null clear tuple',
    )
  }

  if (
    !isFiniteNumber(minLat)
    || !isFiniteNumber(maxLat)
    || !isFiniteNumber(minLng)
    || !isFiniteNumber(maxLng)
  ) {
    throw new FloorGpsBoundsError(
      'INVALID_REQUEST',
      'minLat, maxLat, minLng, and maxLng must be finite numbers or all null',
    )
  }

  if (minLat >= maxLat || minLng >= maxLng) {
    throw new FloorGpsBoundsError(
      'BOUNDS_RANGE_INVALID',
      'GPS bounds must satisfy minLat < maxLat and minLng < maxLng',
    )
  }

  return {
    gpsMinLat: minLat,
    gpsMaxLat: maxLat,
    gpsMinLng: minLng,
    gpsMaxLng: maxLng,
  }
}

/**
 * Converts nullable DB floor GPS columns into a complete GPS bounds object.
 * Returns null when any value is missing (or non-finite), ensuring callers never
 * serialize partial coordinate tuples.
 */
export function toNavFloorGpsBounds(row: FloorGpsBoundsColumns): NavFloorGpsBounds | null {
  if (
    !isFiniteNumber(row.gpsMinLat)
    || !isFiniteNumber(row.gpsMaxLat)
    || !isFiniteNumber(row.gpsMinLng)
    || !isFiniteNumber(row.gpsMaxLng)
  ) {
    return null
  }

  return {
    minLat: row.gpsMinLat,
    maxLat: row.gpsMaxLat,
    minLng: row.gpsMinLng,
    maxLng: row.gpsMaxLng,
  }
}

export function serializeFloorGpsBounds(row: FloorGpsBoundsColumns): { gpsBounds?: NavFloorGpsBounds } {
  const gpsBounds = toNavFloorGpsBounds(row)
  return gpsBounds ? { gpsBounds } : {}
}

export function parseFloorGpsBoundsUpdatePayload(payload: unknown): FloorGpsBoundsColumns {
  if (!isRecord(payload)) {
    throw new FloorGpsBoundsError('INVALID_REQUEST', 'Request body must be a JSON object')
  }

  return parseFloorGpsBoundsTuple({
    minLat: payload.minLat,
    maxLat: payload.maxLat,
    minLng: payload.minLng,
    maxLng: payload.maxLng,
  })
}

function createDrizzleStoreTx(tx: DrizzleFloorGpsBoundsTx): FloorGpsBoundsStoreTx {
  return {
    async getFloorById(floorId) {
      const [row] = await tx
        .select({
          id: floors.id,
          gpsMinLat: floors.gpsMinLat,
          gpsMaxLat: floors.gpsMaxLat,
          gpsMinLng: floors.gpsMinLng,
          gpsMaxLng: floors.gpsMaxLng,
        })
        .from(floors)
        .where(eq(floors.id, floorId))
        .limit(1)

      return row ?? null
    },

    async updateFloorGpsBounds(floorId, bounds) {
      const [row] = await tx
        .update(floors)
        .set({
          ...bounds,
          updatedAt: new Date().toISOString(),
        })
        .where(eq(floors.id, floorId))
        .returning({
          id: floors.id,
          gpsMinLat: floors.gpsMinLat,
          gpsMaxLat: floors.gpsMaxLat,
          gpsMinLng: floors.gpsMinLng,
          gpsMaxLng: floors.gpsMaxLng,
        })

      return row ?? null
    },
  }
}

const drizzleFloorGpsBoundsStore: FloorGpsBoundsStore = {
  transaction(callback) {
    return db.transaction(async (tx) => callback(createDrizzleStoreTx(tx)))
  },
}

async function executeUpdateFloorGpsBounds(
  tx: FloorGpsBoundsStoreTx,
  floorId: number,
  bounds: FloorGpsBoundsColumns,
): Promise<FloorGpsBoundsUpdateResult> {
  const existingFloor = await tx.getFloorById(floorId)
  if (!existingFloor) {
    throw new FloorGpsBoundsError('FLOOR_NOT_FOUND', `Floor ${floorId} was not found`)
  }

  const updatedFloor = await tx.updateFloorGpsBounds(existingFloor.id, bounds)
  if (!updatedFloor) {
    throw new FloorGpsBoundsError('FLOOR_NOT_FOUND', `Floor ${floorId} was not found`)
  }

  return {
    ok: true,
    floorId: updatedFloor.id,
    gpsBounds: toNavFloorGpsBounds(updatedFloor),
  }
}

export async function updateFloorGpsBounds(
  floorId: number,
  bounds: FloorGpsBoundsColumns,
  options?: { store?: FloorGpsBoundsStore },
): Promise<FloorGpsBoundsUpdateResult> {
  if (!Number.isInteger(floorId) || floorId <= 0) {
    throw new FloorGpsBoundsError('INVALID_REQUEST', 'floorId must be a positive integer')
  }

  const store = options?.store ?? drizzleFloorGpsBoundsStore
  return store.transaction(async (tx) => executeUpdateFloorGpsBounds(tx, floorId, bounds))
}

export async function updateFloorGpsBoundsFromPayload(
  floorId: number,
  payload: unknown,
  options?: { store?: FloorGpsBoundsStore },
): Promise<FloorGpsBoundsUpdateResult> {
  const bounds = parseFloorGpsBoundsUpdatePayload(payload)
  return updateFloorGpsBounds(floorId, bounds, options)
}

