import type { NavGraph } from '../../src/shared/types';
import { validateNavGraphPayload } from '../domain/navGraphSchema';

export type MapApiErrorReason =
  | 'http-error'
  | 'network-error'
  | 'timeout'
  | 'aborted'
  | 'invalid-json'
  | 'contract-validation-error'
  | 'unexpected-content-type';

export interface MapApiError {
  endpoint: string;
  status: number | null;
  reason: MapApiErrorReason;
  attempt: number;
  message: string;
  details?: string[];
}

export type MapApiResult<T> =
  | {
      ok: true;
      endpoint: string;
      status: number;
      attempt: number;
      data: T;
    }
  | {
      ok: false;
      error: MapApiError;
    };

export interface MapImageContract {
  endpoint: string;
  contentType: string;
  cacheControl: string | null;
}

export interface FloorPlanTarget {
  buildingId: number;
  floorNumber: number;
}

export interface MapApiRetryPolicy {
  maxAttempts: number;
  baseDelayMs: number;
  timeoutMs: number;
}

export interface MapApiClientConfig {
  baseUrl: string;
  fetchImpl?: typeof fetch;
  retryPolicy?: Partial<MapApiRetryPolicy>;
  sleep?: (ms: number) => Promise<void>;
}

export interface MapApiRequestOptions {
  signal?: AbortSignal;
  maxAttempts?: number;
  timeoutMs?: number;
}

interface AttemptSignal {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
}

interface HttpSuccess {
  ok: true;
  endpoint: string;
  attempt: number;
  response: Response;
}

interface HttpFailure {
  ok: false;
  error: MapApiError;
}

const DEFAULT_RETRY_POLICY: MapApiRetryPolicy = {
  maxAttempts: 3,
  baseDelayMs: 200,
  timeoutMs: 2_000,
};

function normalizeBaseUrl(baseUrl: string): string {
  const parsed = new URL(baseUrl);
  parsed.hash = '';
  parsed.search = '';
  return parsed.toString().replace(/\/$/, '');
}

function resolveEndpoint(baseUrl: string, pathname: string): string {
  return new URL(pathname, `${baseUrl}/`).toString();
}

function createApiError(
  endpoint: string,
  attempt: number,
  reason: MapApiErrorReason,
  message: string,
  status: number | null = null,
  details?: string[],
): MapApiError {
  return {
    endpoint,
    status,
    reason,
    attempt,
    message,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function isRetryableHttpStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

function isAbortError(error: unknown): boolean {
  if (error instanceof DOMException) {
    return error.name === 'AbortError';
  }

  return error instanceof Error && error.name === 'AbortError';
}

function createAttemptSignal(externalSignal: AbortSignal | undefined, timeoutMs: number): AttemptSignal {
  const controller = new AbortController();
  let timeoutTriggered = false;

  const onExternalAbort = () => {
    controller.abort(externalSignal?.reason);
  };

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }

  const timeoutHandle = setTimeout(() => {
    timeoutTriggered = true;
    controller.abort(new Error('timeout'));
  }, timeoutMs);

  const cleanup = () => {
    clearTimeout(timeoutHandle);
    if (externalSignal && !externalSignal.aborted) {
      externalSignal.removeEventListener('abort', onExternalAbort);
    }
  };

  return {
    signal: controller.signal,
    cleanup,
    didTimeout: () => timeoutTriggered,
  };
}

function createSleepWithSignal(
  sleepImpl: (ms: number) => Promise<void>,
  signal: AbortSignal | undefined,
): (ms: number) => Promise<void> {
  return async (ms: number) => {
    if (ms <= 0) {
      return;
    }

    if (!signal) {
      await sleepImpl(ms);
      return;
    }

    if (signal.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }

    await new Promise<void>((resolve, reject) => {
      const timeoutHandle = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, ms);

      const onAbort = () => {
        clearTimeout(timeoutHandle);
        reject(new DOMException('Aborted', 'AbortError'));
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  };
}

export interface MapApiClient {
  fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>>;
  fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>>;
  fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>>;
  resolveMapUrl(): string;
  resolveFloorPlanImageUrl(target: FloorPlanTarget): string;
  resolveCampusImageUrl(): string;
}

export function createMapApiClient(config: MapApiClientConfig): MapApiClient {
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const fetchImpl = config.fetchImpl ?? fetch;
  const retryPolicy: MapApiRetryPolicy = {
    ...DEFAULT_RETRY_POLICY,
    ...config.retryPolicy,
  };
  const sleepImpl = config.sleep ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));

  async function executeGet(
    endpoint: string,
    options: MapApiRequestOptions | undefined,
  ): Promise<HttpSuccess | HttpFailure> {
    const maxAttempts = options?.maxAttempts ?? retryPolicy.maxAttempts;
    const timeoutMs = options?.timeoutMs ?? retryPolicy.timeoutMs;
    const sleepWithSignal = createSleepWithSignal(sleepImpl, options?.signal);

    let lastError: MapApiError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      const attemptSignal = createAttemptSignal(options?.signal, timeoutMs);

      try {
        const response = await fetchImpl(endpoint, {
          method: 'GET',
          signal: attemptSignal.signal,
        });

        if (!response.ok) {
          const error = createApiError(
            endpoint,
            attempt,
            'http-error',
            `Request failed with HTTP ${response.status}.`,
            response.status,
          );

          if (attempt < maxAttempts && isRetryableHttpStatus(response.status)) {
            lastError = error;
            const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
            await sleepWithSignal(delay);
            continue;
          }

          return { ok: false, error };
        }

        return {
          ok: true,
          endpoint,
          attempt,
          response,
        };
      } catch (error) {
        const reason: MapApiErrorReason = attemptSignal.didTimeout()
          ? 'timeout'
          : options?.signal?.aborted || isAbortError(error)
            ? 'aborted'
            : 'network-error';

