import type { NavGraph } from '../../src/shared/types';
import { describe, expect, it, vi } from 'vitest';
import {
  createMapApiClient,
  resolveCampusImageEndpoint,
  resolveFloorPlanImageEndpoint,
  resolveMapEndpoint,
} from './mapApiClient';

function createGraphFixture(): NavGraph {
  return {
    buildings: [
      {
        id: 1,
        name: 'Engineering',
        floors: [
          {
            id: 11,
            floorNumber: 1,
            imagePath: 'floor-plan-1-1.png',
            updatedAt: '2026-01-01T00:00:00.000Z',
            nodes: [
              {
                id: 'entrance-1',
                x: 0.1,
                y: 0.2,
                label: 'Main Entrance',
                type: 'entrance',
                searchable: true,
                floorId: 11,
              },
              {
                id: 'stairs-1',
                x: 0.3,
                y: 0.4,
                label: 'Stairs',
                type: 'stairs',
                searchable: false,
                floorId: 11,
                connectsToFloorAboveId: 12,
                connectsToNodeAboveId: 'stairs-2',
              },
            ],
            edges: [
              {
                id: 'edge-1',
                sourceId: 'entrance-1',
                targetId: 'stairs-1',
                standardWeight: 0.5,
                accessibleWeight: 10000000000,
                accessible: false,
                bidirectional: true,
              },
            ],
          },
        ],
      },
    ],
  };
}

describe('mapApiClient', () => {
  it('resolves endpoint URLs for map, floor image, and campus image', () => {
    expect(resolveMapEndpoint('https://campusnav.example.com/')).toBe('https://campusnav.example.com/api/map');
    expect(resolveFloorPlanImageEndpoint('https://campusnav.example.com', { buildingId: 4, floorNumber: 2 })).toBe(
      'https://campusnav.example.com/api/floor-plan/4/2',
    );
    expect(resolveCampusImageEndpoint('https://campusnav.example.com')).toBe(
      'https://campusnav.example.com/api/campus/image',
    );
  });

  it('fetches and validates map payload successfully', async () => {
    const payload = createGraphFixture();
    const fetchImpl = vi.fn<typeof fetch>().mockResolvedValue(
      new Response(JSON.stringify(payload), {
        status: 200,
        headers: {
          'content-type': 'application/json',
        },
      }),
    );

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 2, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(true);
    if (!result.ok) {
      throw new Error('Expected map request to succeed.');
    }

    expect(result.endpoint).toBe('https://campusnav.example.com/api/map');
    expect(result.status).toBe(200);
    expect(result.attempt).toBe(1);
    expect(result.data.buildings[0]?.floors[0]?.nodes[1]?.connectsToNodeAboveId).toBe('stairs-2');
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('retries retryable HTTP failures and reports successful attempt count', async () => {
    const payload = createGraphFixture();
    const fetchImpl = vi
      .fn<typeof fetch>()
      .mockResolvedValueOnce(new Response('service unavailable', { status: 500 }))
      .mockResolvedValueOnce(
        new Response(JSON.stringify(payload), {
          status: 200,
          headers: {
            'content-type': 'application/json',
          },
        }),
      );

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(true);
    if (!result.ok) {
      throw new Error('Expected map request to succeed after retry.');
    }

    expect(result.attempt).toBe(2);
    expect(fetchImpl).toHaveBeenCalledTimes(2);
  });

  it('returns structured endpoint/status/reason metadata for non-retryable HTTP errors', async () => {
    const fetchImpl = vi.fn<typeof fetch>().mockResolvedValue(new Response('missing', { status: 404 }));
    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected HTTP failure.');
    }

    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/map');
    expect(result.error.status).toBe(404);
    expect(result.error.reason).toBe('http-error');
    expect(result.error.attempt).toBe(1);
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('classifies timeout failures after bounded retries', async () => {
    const timeoutFetch = vi.fn<typeof fetch>((_input, init) => {
      return new Promise<Response>((_, reject) => {
        init?.signal?.addEventListener(
          'abort',
          () => reject(new DOMException('Aborted', 'AbortError')),
          { once: true },
        );
      });
    });

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl: timeoutFetch,
      retryPolicy: { maxAttempts: 2, baseDelayMs: 0, timeoutMs: 5 },
    });

    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected timeout failure.');
    }

    expect(result.error.reason).toBe('timeout');
    expect(result.error.attempt).toBe(2);
    expect(result.error.status).toBeNull();
    expect(timeoutFetch).toHaveBeenCalledTimes(2);
  });

  it('classifies caller cancellation as aborted without extra retries', async () => {
    const abortingFetch = vi.fn<typeof fetch>((_input, init) => {
      return new Promise<Response>((_, reject) => {
        init?.signal?.addEventListener(
          'abort',
          () => reject(new DOMException('Aborted', 'AbortError')),
          { once: true },
        );
      });
    });

    const client = createMapApiClient({
      baseUrl: 'https://campusnav.example.com',
      fetchImpl: abortingFetch,
      retryPolicy: { maxAttempts: 3, baseDelayMs: 0, timeoutMs: 50 },
    });

    const controller = new AbortController();
    controller.abort();

    const result = await client.fetchMapGraph({ signal: controller.signal });

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected aborted request result.');
    }

    expect(result.error.reason).toBe('aborted');
    expect(result.error.attempt).toBe(1);
    expect(abortingFetch).toHaveBeenCalledTimes(1);
  });

  it('returns invalid-json when response body cannot be parsed as JSON', async () => {
    const fetchImpl = vi.fn<typeof fetch>().mockResolvedValue(
      new Response('this is not json', {
        status: 200,
        headers: { 'content-type': 'application/json' },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected invalid JSON failure.');
    }

    expect(result.error.reason).toBe('invalid-json');
    expect(result.error.status).toBe(200);
    expect(result.error.endpoint).toContain('/api/map');
  });

  it('returns contract-validation-error with details for malformed map payloads', async () => {
    const fetchImpl = vi.fn<typeof fetch>().mockResolvedValue(
      new Response(JSON.stringify({ foo: 'bar' }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchMapGraph();

    expect(result.ok).toBe(false);
    if (result.ok) {
      throw new Error('Expected contract validation failure.');
    }

    expect(result.error.reason).toBe('contract-validation-error');
    expect(result.error.details?.[0]).toContain('buildings');
    expect(result.error.endpoint).toBe('https://campusnav.example.com/api/map');
  });

  it('returns unexpected-content-type for image contract endpoints with non-image responses', async () => {
    const fetchImpl = vi.fn<typeof fetch>().mockResolvedValue(
      new Response('not image', {
        status: 200,
        headers: {
          'content-type': 'application/json',
        },
      }),
    );

    const client = createMapApiClient({ baseUrl: 'https://campusnav.example.com', fetchImpl });
    const result = await client.fetchCampusImageContract();

    expect(result.ok).toBe(false);
    if (result.ok) {
